def format_bytes(n):
    """Return a human-readable byte size string, e.g. '1.5 KB'."""
    for unit, exp in [("KB", 1), ("MB", 2), ("GB", 3), ("TB", 4)]:
        threshold = 1024 ** (exp + 1)
        if n < threshold:
            value = n / (1024 ** exp)
            if value == int(value):
                return f"{int(value)} {unit}"
            return f"{value:.1f} {unit}"
    return f"{n} B"
